## Why it exists

A web page can contain code from many authors: your scripts, an analytics snippet, an ad, a comment typed by a stranger. And your browser holds the keys to many accounts at once: the cookies for your bank, your email and your company's admin panel. The browser's **security model** is the set of rules that keeps one site's code from reading or abusing another site's data. Most "web security headers" and most mysterious browser errors ("blocked by CORS policy", "refused to execute inline script") are this model talking.

The rules are easy to misremember, and wrong beliefs cause real incidents: "CORS protects my API" (it does not), "HttpOnly stops XSS" (it does not; it only stops cookie theft), "our CSP is on" (but with `unsafe-inline` it does little). Instead of reciting rules, this lesson **tests each one in headless Chromium** against two small local servers, so every claim is something a browser actually did.

**Mental model:** the browser is a building with a separate locked room for every **origin** (scheme + host + port). Code may run freely in its own room and may *send* mail to other rooms, but it may only *read* replies from another room if that room's owner has written permission on the door (CORS). Extra locks you can add to your own room: a policy about which scripts may run (CSP), cookie attributes about who may carry them (`HttpOnly`, `SameSite`, `Secure`), and a rule about whether others may put your room inside their window (framing).

{{dg:0}}

## How it works

The test rig is one Python file serving two origins on `localhost` (ports 9100 and 9101) and one Node.js script that drives headless Chromium with Playwright, records what page JavaScript could do, and asks the server what it actually received. The page origin is `http://localhost:9100`; the "API" is `http://localhost:9101`. Full code:

```python
"""One process, two ports: http://localhost:9100 (a 'web' origin) and http://localhost:9101 (an 'api' origin)."""
import json
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlsplit

LOG = []   # what the API server actually received


def page(body, extra=""):
    return f"<!doctype html><meta charset=utf-8><title>demo</title>{extra}{body}"


CORS_PAGE = page("""<script>
const api = "http://localhost:9101";
const tests = {
  "A simple GET, server sends no CORS header":  () => fetch(api + "/nocors"),
  "B simple GET, server allows any origin (*)": () => fetch(api + "/public"),
  "C POST text/plain to a no-CORS endpoint":    () => fetch(api + "/nocors", {method: "POST", body: "transfer=100", headers: {"Content-Type": "text/plain"}}),
  "D custom header, server answers preflight":  () => fetch(api + "/pref", {headers: {"X-Token": "abc"}}),
  "E custom header, server ignores preflight":  () => fetch(api + "/nocors", {headers: {"X-Token": "abc"}}),
  "F cookies sent, server allows this origin":  () => fetch(api + "/cred", {credentials: "include"}),
  "G cookies sent, server answers with *":      () => fetch(api + "/cred-star", {credentials: "include"}),
};
window.__results = {};
(async () => {
  for (const [name, run] of Object.entries(tests)) {
    try {
      const res = await run();
      window.__results[name] = "JS can read it: " + res.status + " " + (await res.text()).trim();
    } catch (error) {
      window.__results[name] = "JS blocked: " + error.name + ": " + error.message;
    }
  }
  window.__done = true;
})();
</script>""")

CSP_INLINE = page("""<p id=out>waiting</p>
<script>window.inlineRan = true;</script>
<script src="/app.js"></script>""")

CSP_NONCE = page("""<script nonce="r4nd0m">window.withNonce = true;</script>
<script>window.withoutNonce = true;</script>""")

ATTACK = page("""<h1>evil page on a different site</h1>
<form id=f method=POST action="http://localhost:9101/transfer"><input name=amount value=100></form>
<a id=go href="http://localhost:9101/transfer-get">click me</a>
<iframe id=denied src="http://localhost:9101/framed-deny"></iframe>
<iframe id=allowed src="http://localhost:9101/framed-ok"></iframe>""")

DASH = page("""<script>document.cookie = "theme=dark; SameSite=Lax"; window.visible = document.cookie;</script>""")


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *args):
        pass

    def reply(self, status=200, body="", ctype="text/html; charset=utf-8", headers=None):
        data = body.encode()
        self.send_response_only(status)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(data)))
        for name, value in (headers or []):
            self.send_header(name, value)
        self.end_headers()
        self.wfile.write(data)

    def record(self, note=""):
        LOG.append({"method": self.command, "path": self.path, "origin": self.headers.get("Origin"),
                    "cookie": sorted(c.split("=")[0] for c in self.headers.get("Cookie", "").split("; ") if c), "note": note})

    def handle_any(self):
        self.rfile.read(int(self.headers.get("Content-Length", 0)))   # always consume the body, or keep-alive breaks
        port = self.server.server_address[1]
        path = urlsplit(self.path).path
        if path == "/__log":
            return self.reply(200, json.dumps(LOG), "application/json")
        if path == "/__reset":
            LOG.clear()
            return self.reply(200, "ok")
        if port == 9100:
            return self.web(path)
        return self.api(path)

    def web(self, path):
        if path == "/cors.html":
            return self.reply(body=CORS_PAGE)
        if path == "/csp-inline.html":
            return self.reply(body=CSP_INLINE, headers=[("Content-Security-Policy", "default-src 'self'")])
        if path == "/csp-nonce.html":
            return self.reply(body=CSP_NONCE, headers=[("Content-Security-Policy", "script-src 'nonce-r4nd0m'")])
        if path == "/app.js":
            return self.reply(body="window.externalRan = true;", ctype="text/javascript")
        if path == "/attack.html":
            return self.reply(body=ATTACK)
        self.reply(404, "not found")

    def api(self, path):
        cors_origin = ("Access-Control-Allow-Origin", "http://localhost:9100")
        if path == "/nocors":
            self.record("received")
            return self.reply(200, '{"secret": "only the server should decide who reads this"}', "application/json")
        if path == "/public":
            self.record("received")
            return self.reply(200, '{"public": true}', "application/json", [("Access-Control-Allow-Origin", "*")])
        if path == "/pref":
            if self.command == "OPTIONS":
                self.record("preflight answered")
                return self.reply(204, "", headers=[cors_origin, ("Access-Control-Allow-Methods", "GET"),
                                                    ("Access-Control-Allow-Headers", "x-token"), ("Access-Control-Max-Age", "600")])
            self.record("real request")
            return self.reply(200, '{"token_ok": true}', "application/json", [cors_origin])
        if path == "/cred":
            self.record("received")
            return self.reply(200, '{"cookies_seen": %s}' % json.dumps(sorted(c.split("=")[0] for c in self.headers.get("Cookie", "").split("; ") if c)),
                              "application/json", [cors_origin, ("Access-Control-Allow-Credentials", "true"), ("Vary", "Origin")])
        if path == "/cred-star":
            self.record("received")
            return self.reply(200, '{"x": 1}', "application/json", [("Access-Control-Allow-Origin", "*"), ("Access-Control-Allow-Credentials", "true")])
        if path == "/login":
            cookies = [("Set-Cookie", "sid=s3cret; HttpOnly; SameSite=Lax; Path=/"),
                       ("Set-Cookie", "lax=1; SameSite=Lax; Path=/"),
                       ("Set-Cookie", "strict=1; SameSite=Strict; Path=/"),
                       ("Set-Cookie", "none=1; SameSite=None; Secure; Path=/")]
            return self.reply(200, page("<p>logged in</p>"), headers=cookies)
        if path in ("/transfer", "/transfer-get"):
            self.record("state-changing request" if path == "/transfer" else "top-level navigation")
            return self.reply(200, page("<p>done</p>"))
        if path == "/framed-deny":
            return self.reply(200, page("<p>sensitive page</p>"), headers=[("X-Frame-Options", "DENY")])
        if path == "/framed-ok":
            return self.reply(200, page("<p>public widget</p>"))
        if path == "/dashboard.html":
            return self.reply(200, DASH)
        self.reply(404, "not found")

    do_GET = do_POST = do_OPTIONS = handle_any


for port in (9100, 9101):
    server = ThreadingHTTPServer(("127.0.0.1", port), Handler)
    threading.Thread(target=server.serve_forever, daemon=True).start()
print("servers up on 9100 and 9101", flush=True)
threading.Event().wait()
```

